#include <iostream>
#include <cstdio>
#include <cmath>
#include <iomanip>
#include <climits>
using namespace std;
bool nhuan(int y) {
    return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
}
int soNgay(int m, int y) {
    switch (m) {
        case 4: case 6: case 9: case 11: return 30;
        case 2: return nhuan(y) ? 29 : 28;
        default: return 31;
    }
}
int stt(int d, int m, int y) {
    int s = d;
    for (int i = 1; i < m; i++) s += soNgay(i, y);
    return s;
}
int main() {
cout << stt(1, 3, 2024) << " " << stt(1, 3, 1900) << " " << stt(31, 12, 2023);
    return 0;
}
